      uri: FILE_URI,
      success: function(data) { cb(String(data && data.text ? data.text : '')) },
      fail: function() { cb('') }
    })
  } catch (e) { cb('') }
}

function writeFile(text) {
  try { file.writeText({ uri: FILE_URI, text: text, append: false, fail: function() {} }) } catch (e) {}
}

function parse(text) {
  var deviceCode = ''
  var activated = false
  var lines = String(text || '').split('\n')
  for (var i = 0; i < lines.length; i++) {
    var line = lines[i].replace(/\r/g, '').trim()
    if (line.indexOf('deviceCode=') === 0) deviceCode = line.slice(11).trim()
    if (line.indexOf('activated=') === 0) activated = line.slice(10).trim() === '1'
  }
  return { deviceCode: deviceCode, activated: activated }
}

function buildText(deviceCode, activated) {
  return 'deviceCode=' + deviceCode + '\n' + 'activated=' + (activated ? '1' : '0')
}

// 读全部授权信息（文件为准，storage 兜底）
