    file.writeText({ uri: FILE_URI, text: text, append: false, fail: function() {}, complete: function() {} })
  } catch (e) {}
}

function parse(text) {
  var deviceCode = ''
  var activated = false
  var lines = String(text || '').split('\n')
  for (var i = 0; i < lines.length; i++) {
    var line = lines[i].replace(/\r/g, '')
    if (line.indexOf('deviceCode=') === 0) deviceCode = line.substring(11).trim()
    if (line.indexOf('activated=') === 0) activated = line.substring(10).trim() === '1'
  }
  return { deviceCode: deviceCode, activated: activated }
}

