import file from "@system.file"
import storage from "@system.storage"
import device from "@system.device"

var FILE_URI = 'internal://files/license.dat'

function readFile(cb) {
  try {
    file.readText({
      uri: FILE_URI,
      success: function(data) { cb(String(data && data.text ? data.text : '')) },
      fail: function() { cb('') },
      complete: function() {}
    })
  } catch (e) {
    cb('')
  }
}

function writeFile(text) {
  try {
    file.writeText({ uri: FILE_URI, text: text, append: false, fail: function() {}, complete: function() {} })
  } catch (e) {}
}

function parse(text) {
  var deviceCode = ''
  var activated = false
  var lines = String(text || '').split('\n')
  for (var i = 0; i < lines.length; i++) {
    var line = lines[i].replace(/\r/g, '')
    if (line.indexOf('deviceCode=') === 0) deviceCode = line.substring(11).trim()
    if (line.indexOf('activated=') === 0) activated = line.substring(10).trim() === '1'
  }
  return { deviceCode: deviceCode, activated: activated }
}

function buildText(deviceCode, activated) {
  return 'deviceCode=' + deviceCode + '\nactivated=' + (activated ? '1' : '0')
}

export function deriveCode(deviceId) {
  var h = 2166136261
  var s = String(deviceId || '')
  for (var i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i)
    h = (h * 16777619) >>> 0
  }
  return String(100000 + (h % 900000))
}

export function genDeviceCode() {
  return String(Math.floor(100000 + Math.random() * 900000))
}

export function loadLicense(cb) {
  readFile(function(text) {
    var lic = parse(text)
    if (lic.deviceCode) {
      cb(lic)
      return
    }
    var dc = ''
    var ac = false
    var n = 0
    function one() {
      n++
      if (n >= 2) {
        if (dc) {
          writeFile(buildText(dc, ac))
          cb({ deviceCode: dc, activated: ac })
        } else {
          cb({ deviceCode: '', activated: false })
        }
      }
    }
    storage.get({
      key: 'deviceCode',
      success: function(d) { dc = d && /^\d{6}$/.test(String(d)) ? String(d) : ''; one() },
      fail: function() { one() }
    })
    storage.get({
      key: 'activated',
      success: function(a) { ac = a === '1'; one() },
      fail: function() { one() }
    })
  })
}

function makeFromDeviceId(cb) {
  try {
    device.getDeviceId({
      success: function(data) {
        if (data && data.deviceId) {
          cb(deriveCode(data.deviceId))
        } else {
          cb('')
        }
      },
      fail: function() { cb('') }
    })
  } catch (e) {
    cb('')
  }
}

export function getDeviceCode(cb) {
  loadLicense(function(lic) {
    if (lic.deviceCode) {
      cb(lic.deviceCode)
      return
    }
    makeFromDeviceId(function(code) {
      if (!code) code = genDeviceCode()
      persistDeviceCode(code)
      cb(code)
    })
  })
}

function persistDeviceCode(code) {
  loadLicense(function(lic) {
    writeFile(buildText(code, lic.activated))
    storage.set({ key: 'deviceCode', data: code })
  })
}

export function getActivated(cb) {
  loadLicense(function(lic) {
    cb(lic.activated)
  })
}

export function setActivated() {
  loadLicense(function(lic) {
    var code = lic.deviceCode || genDeviceCode()
    writeFile(buildText(code, true))
    storage.set({ key: 'deviceCode', data: code })
    storage.set({ key: 'activated', data: '1' })
  })
}

export function makeActivationCode(dev) {
  var s = String(dev || '')
  var mid = ''
  for (var i = 0; i < s.length; i++) {
    mid += String(parseInt(s.charAt(i), 10) + 3)
  }
  var n = parseInt(mid, 10) || 0
  return ('000000' + (n + 888888)).slice(-6)
}

export function checkActivation(dev, input) {
  var s = String(input || '').trim()
  if (!/^\d{6}$/.test(s)) return false
  return s === makeActivationCode(dev)
}

