display.text:
  protected: {
    deviceCode: ''
  },
  private: {
    entered: '',
    display: '',
    msg: '',
    failed: false,
    done: false
  },

  onInit() {
    this.deviceCode = this.deviceCode || ''
  },

  tap(n) {
    if (this.done) return
    if (this.entered.length >= 6) return
    this.msg = ''
    this.failed = false
    this.entered += n
    this.updateDisplay()
    if (this.entered.length === 6) this.doConfirm()
  },

  del() {
    if (this.done) return
    this.entered = this.entered.slice(0, -1)
    this.updateDisplay()
  },

  updateDisplay() {
    if (this.entered.length <= 3) {
      this.display = this.entered
    } else {
      this.display = this.entered.slice(0, 3) + ' ' + this.entered.slice(3)
    }
  },

  doConfirm() {
    if (this.done) return
    if (this.entered.length !== 6) {
      this.failed = true
      this.msg = '请输入6位激活码'
      return
    }
    if (checkActivation(this.deviceCode, this.entered)) {
      storage.set({ key: 'activated', data: '1' })
      this.failed = false
      this.msg = '激活成功'
      this.done = true
      setTimeout(function() {
        router.back()
      }, 1200)
    } else {
      this.failed = true
      this.msg = '激活码错误'
      this.entered = ''
      this.display = ''
    }
  },

  onSwipe(e) {
    if (e.direction === 'right' && !this.done) {
      router.back()
    }
  }
}
