tick() {
  if (this.controlMode === 0) {
    if (!this.calibDone) {
      this.calibSamples.push(this.sensorX)
      if (this.calibSamples.length >= 15) {
        var sum = 0
        for (var ci = 0; ci < this.calibSamples.length; ci++) sum += this.calibSamples[ci]
        this.baselineX = sum / this.calibSamples.length
        this.calibDone = true
      }
    } else {
      var rawX = this.sensorX - this.baselineX
      this.filteredX = this.filteredX * 0.7 + rawX * 0.3
      var DEAD = 0.5
      var tilt = this.filteredX
      if (tilt > -DEAD && tilt < DEAD) tilt = 0
      this.px -= tilt * (this.level === 3 ? 0.7 : 0.6)
    }
  }
  if (this.px < this.playL) this.px = this.playL
  if (this.px > this.playR - this.pw) this.px = this.playR - this.pw

