      this['b' + i + 'y'] = -999
      this['b' + i + 'c'] = '#333333'
      this['b' + i + 's'] = ''
      this['b' + i + 'k'] = 0
    }
    if (this.level === 2) this.assignHealthBricks()
    this.assignSpecialBricks(idx)
  },

  assignSpecialBricks(count) {
    var specialC = { 1: '#ff7777', 2: '#55dd77', 3: '#5599ee' }
    var picked = {}
    var kinds = [1, 2, 3]
    for (var k = 0; k < kinds.length && count > 0; k++) {
      var pos = -1
      var guard = 0
      do {
        pos = Math.floor(Math.random() * count)
        guard++
      } while (picked[pos] && guard < 50)
      if (picked[pos]) continue
      picked[pos] = true
      this['b' + pos + 'k'] = kinds[k]
      this['b' + pos + 'c'] = specialC[kinds[k]]
      this['b' + pos + 's'] = 'border:2px solid #ffffff;'
    }
  },

  assignHealthBricks() {
    var alive = []
    for (var i = 0; i < 20; i++) {
      if (this['b' + i + 'a']) alive.push(i)
    }
    var total = alive.length
    for (var j = 0; j < total; j++) {
      this['b' + alive[j] + 'c'] = '#ffcc00'
    }
    var redCount = Math.min(4, Math.floor(total * 0.2))
    var greenCount = Math.min(3, Math.floor(total * 0.15))
    var blueCount = Math.min(3, Math.floor(total * 0.15))
    var idx = 0
    var placed = 0
    var redPlaced = 0
    while (placed < total && redPlaced < redCount) {
      this['b' + alive[placed] + 'c'] = '#ff3333'
      placed++
      redPlaced++
    }
    var greenPlaced = 0
    while (placed < total && greenPlaced < greenCount) {
      this['b' + alive[placed] + 'c'] = '#33cc33'
      placed++
      greenPlaced++
    }
    var bluePlaced = 0
    while (placed < total && bluePlaced < blueCount) {
      this['b' + alive[placed] + 'c'] = '#3396ff'
      placed++
      bluePlaced++
    }
  },

