input.newString:
aimAtBrick(bx, by, vx, vy) {
    var ret = this._aimRet
    var alive = this._aimAlive
    alive.length = 0
    var totalA = Math.min((2 + this.level) * 5, 20)
    for (var i = 0; i < totalA; i++) {
      if (this[this._ba[i]]) alive.push(i)
    }
    if (alive.length === 0 || alive.length > 3) {
      ret.vx = vx
      ret.vy = vy
      return ret
    }
    var target = alive[Math.floor(Math.random() * alive.length)]
    var dx = this[this._bx[target]] + this.bw / 2 - (bx + this.ballS / 2)
    var dy = this[this._by[target]] + this.bh / 2 - (by + this.ballS / 2)
    var len = Math.sqrt(dx * dx + dy * dy)
    if (len < 1) {
      ret.vx = vx
      ret.vy = vy
      return ret
    }
    var spd = Math.sqrt(vx * vx + vy * vy)
    if (spd < 0.1) spd = 2
    var mix = 0.55
    if (alive.length === 2) mix = 0.4
    if (alive.length === 3) mix = 0.22
    var nx = vx * (1 - mix) + (dx / len) * spd * mix
    var ny = vy * (1 - mix) + (dy / len) * spd * mix
    var ns = Math.sqrt(nx * nx + ny * ny)
    if (ns < 0.1) ns = 1
    ret.vx = nx / ns * spd
    ret.vy = ny / ns * spd
    return ret
  },

