input.newString:
startGame() {
    var self = this
    if (!this._tickFn) {
      this._tickFn = function() {
        self.timer = null
        if (self.state === 0 && !self.paused) {
          self.tick()
          self._gt++
          if (self._gt % 3 === 0) self.gameTime = self._gt / 10
        }
        if (self.state === 0 && !self.paused) self.schedule()
      }
    }
    this.subscribeSensor()
    this.schedule()
  },

  schedule() {
    if (this.timer) return
    this.timer = setTimeout(this._tickFn, 35)
  },

  stopLoop() {
    if (this.timer) {
      clearTimeout(this.timer)
      this.timer = null
    }
  },

  subscribeSensor() {
    var self = this
    if (this.controlMode === 0) {
      try {
        sensor.subscribeAccelerometer({
          interval: 'game',
          callback: function(ret) { self._rawX = ret.x }
        })
      } catch (e) {}
    }
  },

  unsubscribeSensor() {
    try { sensor.unsubscribeAccelerometer() } catch (e) {}
  },

  onDestroy() {
    this.stopLoop()
    this.unsubscribeSensor()
  },

  onHide() {
    if (this.state === 0) {
      this.paused = true
      this.stopLoop()
      this.unsubscribeSensor()
    }
  },

  onShow() {
    if (this.paused && this.state === 0) {
      this.stopLoop()
    }
  },

  onResume() {
    if (!this.paused) return
    this.paused = false
    this.filteredX = 0
    this.calibSamples.length = 0
    this.calibDone = false
    this.baselineX = 0
    this._rawX = 0
    this.subscribeSensor()
    this.schedule()
  },

