buildBricks() {
    var wild = this.isWild
    var rows = wild ? 3 : 4
    var cols = wild ? 5 : 4
    this.bw = wild ? 52 : 64
    var totalW = cols * this.bw + (cols - 1) * this.bpad
    var startX = Math.floor((this.fieldW - totalW) / 2)
    var startY = 232
    var idx = 0
    var normalColors = ['#ff6b6b','#ffb347','#5ad1a5','#5aa9ff','#b987ff']
    for (var r = 0; r < rows; r++) {
      for (var c = 0; c < cols; c++) {
        if (idx >= 20) break
        this[this._bx[idx]] = startX + c * (this.bw + this.bpad)
        this[this._by[idx]] = startY + r * (this.bh + this.bpad)
        this[this._ba[idx]] = true
        this[this._bs[idx]] = ''
        this[this._bk[idx]] = 0
        if (this.isHp) {
          this[this._bc[idx]] = '#ffcc00'
        } else {
          this[this._bc[idx]] = normalColors[(r + c) % normalColors.length]
        }
        idx++
      }
      if (idx >= 20) break
    }

